import{t as e}from"./utils-COoNfFoj.js";var t={slug:`maria-gharib`,influencerName:`Maria Gharib`,influencerHandle:`@MariaGharib`,influencerAvatarUrl:`${e}/maria-gharib-avatar.jpeg`,heroDescription:`I love to socialise, travel, and meet new people. But every time I land in a new city, I don’t know what’s happening or where the cool spots are, so I built a tool that tells me what’s on in any area. Now I can show up, get involved, and meet people.`,assetTitle:`Social Life`,screenshotUrl:`${e}/maria-gharib.png`,remixUrl:`https://www.perplexity.ai/computer/a/social-life-dashboard-6fuSiuBDTHaZUqIqGYp7rw`,promptTitle:`Try Maria's prompt`,promptText:`Build a “Social Life Dashboard” web app that aggregates and surfaces local events from platforms like Eventbrite, Facebook Events, Time Out, and relevant local community groups, then intelligently cross-references them with the user’s calendar (such as Google Calendar) to highlight events they are actually available to attend; include a community and group matching engine that recommends new groups based on user interests and past activity, a “Your Weekend” Friday digest that delivers the top 3 curated event picks with availability pre-validated, a friend activity tracker that shows which events people in the user’s network are attending, and a monthly social recap dashboard summarizing events attended, activity categories, engagement patterns, and personalized recommendations for the upcoming month, all presented in a clean light mode UI with subtle pink highlights, modern card-based layout, and intuitive filters for date, category, and social relevance.`};export{t as default};
